// make_icon.cpp — the application icon, generated by the application.
//
// The workbench shipped without an icon, which is a real gap for something that
// gets pinned to a taskbar. The obvious fix is to go and find one; the better
// fix is that this app already draws things for a living.
//
// So the icon is a GLIDER, simulated rather than drawn: the pattern is stepped
// through Conway's rule by the same LifeLike class the bench ships, and the
// frame that gets rendered is a real generation of a real simulation. It is the
// one shape that reads at 16 pixels and means exactly what this program is.
//
// Writes a multi-resolution .ico with PNG payloads (supported since Vista),
// reusing the bench's own PNG writer — no image library, no third-party asset,
// no licence to track.

#include "sims/life_like.hpp"
#include "render/png.hpp"

#include <cstdio>
#include <cstring>
#include <string>
#include <vector>

namespace {

// Little-endian appenders; .ico is a fixed little-endian layout.
void put16(std::vector<std::uint8_t>& v, unsigned x) {
    v.push_back(std::uint8_t(x & 0xFF)); v.push_back(std::uint8_t((x >> 8) & 0xFF));
}
void put32(std::vector<std::uint8_t>& v, unsigned x) {
    for (int i = 0; i < 4; ++i) v.push_back(std::uint8_t((x >> (8 * i)) & 0xFF));
}

std::vector<std::uint8_t> read_file(const std::string& p) {
    std::vector<std::uint8_t> out;
    if (std::FILE* f = std::fopen(p.c_str(), "rb")) {
        std::fseek(f, 0, SEEK_END); const long n = std::ftell(f); std::fseek(f, 0, SEEK_SET);
        out.resize(std::size_t(n < 0 ? 0 : n));
        if (!out.empty() && std::fread(out.data(), 1, out.size(), f) != out.size()) out.clear();
        std::fclose(f);
    }
    return out;
}

} // namespace

int main(int argc, char** argv) {
    const std::string out = argc > 1 ? argv[1] : "workbench.ico";

    // A 9x9 window around a glider, stepped four generations so it has actually
    // moved — the icon is a simulation result, not a picture of one.
    constexpr int N = 9;
    auto sim = bench::make_life(N);
    auto& L  = *static_cast<bench::LifeLike*>(sim.get());
    L.clear();
    L.put(4, 3); L.put(5, 4); L.put(3, 5); L.put(4, 5); L.put(5, 5);
    for (int i = 0; i < 4; ++i) L.step();

    const int sizes[] = { 16, 32, 48, 64, 128, 256 };
    std::vector<std::vector<std::uint8_t>> pngs;

    for (int S : sizes) {
        std::vector<std::uint8_t> rgba(std::size_t(S) * S * 4, 0);
        // Integer cell size, centred: a non-integer scale makes 16px mush.
        const int cell = S / N > 0 ? S / N : 1;
        const int span = cell * N;
        const int off  = (S - span) / 2;
        const int gap  = cell >= 6 ? 1 : 0;      // hairline grid only when it fits

        for (int y = 0; y < N; ++y)
            for (int x = 0; x < N; ++x) {
                if (!L.field().at(x, y)) continue;
                for (int py = 0; py < cell - gap; ++py)
                    for (int px = 0; px < cell - gap; ++px) {
                        const int sx = off + x * cell + px, sy = off + y * cell + py;
                        if (sx < 0 || sy < 0 || sx >= S || sy >= S) continue;
                        std::uint8_t* p = &rgba[(std::size_t(sy) * S + sx) * 4];
                        p[0] = 90; p[1] = 209; p[2] = 196; p[3] = 255;   // the bench's accent
                    }
            }

        char tmp[64]; std::snprintf(tmp, sizeof tmp, "icon_%d.png", S);
        if (!bench::write_png(tmp, S, S, rgba.data())) {
            std::printf("could not write %s\n", tmp); return 1;
        }
        auto bytes = read_file(tmp);
        std::remove(tmp);
        if (bytes.empty()) { std::printf("could not read back %s\n", tmp); return 1; }
        pngs.push_back(std::move(bytes));
    }

    // ICONDIR, then one ICONDIRENTRY per image, then the payloads.
    const unsigned n = unsigned(pngs.size());
    std::vector<std::uint8_t> ico;
    put16(ico, 0); put16(ico, 1); put16(ico, n);
    unsigned offset = 6 + 16 * n;
    for (unsigned i = 0; i < n; ++i) {
        const int S = sizes[i];
        ico.push_back(std::uint8_t(S == 256 ? 0 : S));   // 0 means 256 in this format
        ico.push_back(std::uint8_t(S == 256 ? 0 : S));
        ico.push_back(0); ico.push_back(0);              // palette count, reserved
        put16(ico, 1); put16(ico, 32);                   // planes, bits per pixel
        put32(ico, unsigned(pngs[i].size()));
        put32(ico, offset);
        offset += unsigned(pngs[i].size());
    }
    for (const auto& p : pngs) ico.insert(ico.end(), p.begin(), p.end());

    std::FILE* f = std::fopen(out.c_str(), "wb");
    if (!f) { std::printf("could not open %s\n", out.c_str()); return 1; }
    std::fwrite(ico.data(), 1, ico.size(), f);
    std::fclose(f);
    std::printf("wrote %s — %u sizes, %zu bytes (a glider, 4 generations in)\n",
                out.c_str(), n, ico.size());
    return 0;
}
